def max_path_sum(tri, m, n):
    """Write a function to find the maximum total path sum in the given triangle.

    A path starts at ``tri[0][0]`` and, at each step, moves to the
    element directly below or directly below and to the right, ending
    anywhere on the last row.  ``m`` and ``n`` give the last row and
    column indices (for example, ``2, 2`` for a 3x3 triangle); passing
    the row/column counts instead is also accepted.  The input is not
    modified.
    """
    if not tri:
        return 0

    rows = len(tri)
    if isinstance(m, int):
        if m < 0:
            return 0
        if m < rows:
            rows = m + 1
    col_limit = n + 1 if isinstance(n, int) and n >= 0 else None

    def width(row_index, row):
        result = min(row_index + 1, len(row))
        if col_limit is not None:
            result = min(result, col_limit)
        return result

    last_index = rows - 1
    last_width = width(last_index, tri[last_index])
    if last_width <= 0:
        return 0
    dp = list(tri[last_index][:last_width])

    for i in range(last_index - 1, -1, -1):
        row = tri[i]
        cur_width = width(i, row)
        if cur_width <= 0:
            return 0
        current = []
        for j in range(cur_width):
            candidates = []
            if j < len(dp):
                candidates.append(dp[j])
            if j + 1 < len(dp):
                candidates.append(dp[j + 1])
            current.append(row[j] + (max(candidates) if candidates else 0))
        dp = current

    return dp[0] if dp else 0
